import {
  Box,
  Breadcrumbs,
  Button,
  Chip,
  Container,
  Divider,
  Grid,
  Link,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Stack,
  Typography,
} from "@mui/material";
import masterData from "../data/masterData.json";
import LeadFormCard from "../components/fellowship/LeadFormCard";
import FeaturedProgramsSection from "../components/fellowship/FeaturedProgramsSection";
import FooterCtaSection from "../components/fellowship/FooterCtaSection";
import {
  ArrowBackIcon,
  CheckCircleOutlineIcon,
  LocationOnOutlinedIcon,
  ScheduleOutlinedIcon,
} from "../utils/iconMap";
import type { Program } from "../types/fellowship";

interface CourseDetailsPageProps {
  specialtyId?: string;
  programId?: string;
  onBack: () => void;
  onLearnMore: (programId: string) => void;
}

export default function CourseDetailsPage({
  specialtyId,
  programId,
  onBack,
  onLearnMore,
}: CourseDetailsPageProps) {
  const { brand, programs, specialties } = masterData;

  const specialty = specialties.find((s) => s.id === specialtyId);
  const program: Program | undefined =
    (programs.find((p) => p.id === programId) as Program | undefined) ||
    (programs.find((p) => p.specialtyId === specialtyId) as Program | undefined) ||
    (programs[0] as Program);

  const related = programs.filter(
    (p) =>
      p.id !== program.id &&
      (specialtyId ? p.specialtyId === specialtyId : p.specialtyId === program.specialtyId)
  ) as Program[];

  const specialtyName =
    specialty?.name ||
    specialties.find((s) => s.id === program.specialtyId)?.name ||
    "Fellowship";

  return (
    <Box component="main" sx={{ bgcolor: "#FAFBFD", minHeight: "100vh" }}>
      <Box
        sx={{
          bgcolor: "#fff",
          borderBottom: "1px solid #E8EEF5",
          py: 2,
          position: "sticky",
          top: 0,
          zIndex: 10,
        }}
      >
        <Container maxWidth="lg">
          <Stack direction="row" alignItems="center" justifyContent="space-between">
            <Stack direction="row" alignItems="center" spacing={1.25}>
              <Box
                component="img"
                src={brand.logo}
                alt={brand.name}
                sx={{ width: 32, height: 32, cursor: "pointer" }}
                onClick={onBack}
              />
              <Typography sx={{ fontWeight: 800, fontSize: 14, letterSpacing: "0.06em" }}>
                {brand.name}
              </Typography>
            </Stack>
            <Button
              startIcon={<ArrowBackIcon />}
              onClick={onBack}
              sx={{ fontWeight: 600 }}
            >
              Back to Home
            </Button>
          </Stack>
        </Container>
      </Box>

      <Box
        sx={{
          background: "linear-gradient(135deg, #003E99 0%, #0056D2 100%)",
          color: "#fff",
          py: { xs: 4, md: 6 },
        }}
      >
        <Container maxWidth="lg">
          <Breadcrumbs
            sx={{
              mb: 2,
              "& .MuiBreadcrumbs-separator, & a, & p": { color: "rgba(255,255,255,0.8)" },
            }}
          >
            <Link component="button" underline="hover" onClick={onBack} sx={{ color: "inherit" }}>
              Home
            </Link>
            <Typography sx={{ color: "#fff" }}>{specialtyName}</Typography>
          </Breadcrumbs>

          {program.isPopular && (
            <Chip
              label="Most Popular"
              size="small"
              sx={{ bgcolor: "rgba(255,255,255,0.2)", color: "#fff", mb: 1.5, fontWeight: 600 }}
            />
          )}

          <Typography
            variant="h3"
            sx={{
              fontWeight: 800,
              fontSize: { xs: "1.6rem", md: "2.4rem" },
              mb: 2,
              maxWidth: 720,
            }}
          >
            {program.title}
          </Typography>

          <Stack direction="row" spacing={3} flexWrap="wrap" useFlexGap>
            <Stack direction="row" spacing={0.75} alignItems="center">
              <ScheduleOutlinedIcon sx={{ fontSize: 20 }} />
              <Typography>{program.duration}</Typography>
            </Stack>
            <Stack direction="row" spacing={0.75} alignItems="center">
              <LocationOnOutlinedIcon sx={{ fontSize: 20 }} />
              <Typography>
                {program.location} · {program.hospital}
              </Typography>
            </Stack>
          </Stack>
        </Container>
      </Box>

      <Container maxWidth="lg" sx={{ py: { xs: 4, md: 6 } }}>
        <Grid container spacing={4}>
          <Grid size={{ xs: 12, md: 8 }}>
            <Box
              component="img"
              src={program.image}
              alt={program.title}
              sx={{
                width: "100%",
                height: { xs: 220, md: 360 },
                objectFit: "cover",
                borderRadius: 3,
                mb: 3,
              }}
            />

            <Box sx={{ bgcolor: "#fff", borderRadius: 3, p: { xs: 2.5, md: 3.5 }, mb: 3, border: "1px solid #E8EEF5" }}>
              <Typography variant="h5" sx={{ fontWeight: 700, color: "#0A2540", mb: 1.5 }}>
                Program Overview
              </Typography>
              <Typography sx={{ color: "text.secondary", lineHeight: 1.75, mb: 3 }}>
                {program.overview}
              </Typography>

              <Divider sx={{ my: 2.5 }} />

              <Typography variant="h6" sx={{ fontWeight: 700, color: "#0A2540", mb: 1.5 }}>
                Key Highlights
              </Typography>
              <List dense disablePadding>
                {program.highlights.map((item) => (
                  <ListItem key={item} disableGutters sx={{ py: 0.5 }}>
                    <ListItemIcon sx={{ minWidth: 36 }}>
                      <CheckCircleOutlineIcon color="primary" fontSize="small" />
                    </ListItemIcon>
                    <ListItemText primary={item} />
                  </ListItem>
                ))}
              </List>

              <Divider sx={{ my: 2.5 }} />

              <Typography variant="h6" sx={{ fontWeight: 700, color: "#0A2540", mb: 1.5 }}>
                Curriculum
              </Typography>
              <List dense disablePadding>
                {program.curriculum.map((item) => (
                  <ListItem key={item} disableGutters sx={{ py: 0.5 }}>
                    <ListItemIcon sx={{ minWidth: 36 }}>
                      <CheckCircleOutlineIcon color="primary" fontSize="small" />
                    </ListItemIcon>
                    <ListItemText primary={item} />
                  </ListItem>
                ))}
              </List>

              <Divider sx={{ my: 2.5 }} />

              <Typography variant="h6" sx={{ fontWeight: 700, color: "#0A2540", mb: 1.5 }}>
                Eligibility
              </Typography>
              <List dense disablePadding>
                {program.eligibility.map((item) => (
                  <ListItem key={item} disableGutters sx={{ py: 0.5 }}>
                    <ListItemIcon sx={{ minWidth: 36 }}>
                      <CheckCircleOutlineIcon color="primary" fontSize="small" />
                    </ListItemIcon>
                    <ListItemText primary={item} />
                  </ListItem>
                ))}
              </List>

              <Divider sx={{ my: 2.5 }} />

              <Grid container spacing={2}>
                <Grid size={{ xs: 12, sm: 6 }}>
                  <Typography variant="subtitle2" color="text.secondary">
                    Course Fee
                  </Typography>
                  <Typography sx={{ fontWeight: 700, color: "#0A2540" }}>{program.fee}</Typography>
                </Grid>
                <Grid size={{ xs: 12, sm: 6 }}>
                  <Typography variant="subtitle2" color="text.secondary">
                    Stipend
                  </Typography>
                  <Typography sx={{ fontWeight: 700, color: "#0A2540" }}>
                    {program.stipend}
                  </Typography>
                </Grid>
              </Grid>
            </Box>
          </Grid>

          <Grid size={{ xs: 12, md: 4 }}>
            <Box sx={{ position: { md: "sticky" }, top: { md: 88 } }}>
              <LeadFormCard defaultSpecialty={program.specialtyId} />
            </Box>
          </Grid>
        </Grid>
      </Container>

      {related.length > 0 && (
        <FeaturedProgramsSection
          programs={related.slice(0, 3)}
          title={`More ${specialtyName} Programs`}
          showViewAll={false}
          onLearnMore={onLearnMore}
        />
      )}

      <FooterCtaSection onTalkToExpert={() => window.scrollTo({ top: 0, behavior: "smooth" })} />
    </Box>
  );
}
